            incidentRecipeService.createMopGenerateRecipeReq(incidentRootAnalysisResult, incident);
        ChainReq chainReq = new ChainReq();
        String report = "";
        try {
            // 执行recipe
            chainReq = ChainProcessor.executeWorkflowDiagnosis(mopgenerateRecipeReq);
            // 获取recipe执行结果内容
            report = ChainProcessor.getWorkflowAnswerResult(chainReq);
            if (report == null) {
                report = "";
                LOGGER.info("[mopGenerate] mop is null");
            }
        } catch (Exception e) {
            LOGGER.error(
                "[mopGenerate] Exception occurred during incident mop generate for incidentCsn={}, msg={}",
                incidentCsn,
                e.getMessage(),
                e);
        } finally {
            if (StringUtils.isNotEmpty(chainReq.getConversationId())) {
                ChainProcessor.closeConversation(chainReq);
            }
        }"}
